apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: { name: default-deny }
spec:
  podSelector: {}
  policyTypes: [Ingress, Egress]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: { name: allow-{{app_label}} }
spec:
  podSelector:
    matchLabels: { app: {{app_label}} }
  ingress:
    - from:
        - podSelector: {}
  egress:
    - to:
        - podSelector: {}
